(function(){'use strict';
const $=s=>document.querySelector(s),S=Staff,M=StaffCash,actor=KashierData.userId(),owner=actor;let epoch=0,request=0,current=null,members=new Map(),rosterRequest=0;
let initial=null,initialError=false;try{const q=new URLSearchParams(location.search||'');if(['member','from','to'].some(k=>q.has(k))){if([...q.keys()].some(k=>!['member','from','to'].includes(k))||['member','from','to'].some(k=>q.getAll(k).length!==1)||!S.uuid(q.get('member')))throw Error();M.range(q.get('from'),q.get('to'));initial={member:q.get('member'),from:q.get('from'),to:q.get('to')};}}catch{initialError=true;}
const destination='owner-cash.html'+(initial?'?'+new URLSearchParams(initial).toString():'');
const active=()=>actor&&KashierData.loggedIn()&&KashierData.userId()===actor,node=(tag,value)=>{const e=document.createElement(tag);if(value!==undefined)e.textContent=String(value);return e;};
function clear(){current=null;$('#staff-cash-paper').hidden=true;$('#staff-cash-rows').replaceChildren();$('#staff-cash-summary').replaceChildren();$('#staff-cash-title').textContent='ڕاپۆرتی کاشی کارمەند';$('#staff-cash-print').disabled=$('#staff-cash-export').disabled=true;}
function invalidate(){request++;clear();$('#staff-cash-status').textContent='کارمەند یان ماوەکە گۆڕاوە؛ ڕاپۆرتەکە نوێ بکەرەوە.';}
function render(v){current=v;$('#staff-cash-title').textContent=v.store_name+' · '+v.member_name;$('#staff-cash-period').textContent=v.from+' — '+v.to+' · کاتی بەغدا';for(const key of ['sale_cash','sale_credit_cash','collection','full_refund','partial_refund','inflow','outflow','net']){const row=node('div');row.append(node('span',M.kinds[key]||{inflow:'کۆی کاشی وەرگیراو',outflow:'کۆی کاشی گەڕێندراو',net:'جیاوازی کاشی مامەڵەکانی کارمەند'}[key]),node('strong',S.format(BigInt(v.summary[key]))+' دینار'));$('#staff-cash-summary').append(row);}for(const r of v.rows){const row=node('tr'),prefix=r.kind==='collection'?'D-':r.kind.includes('refund')?'R-':'K-';row.append(node('td',new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'medium'}).format(new Date(r.created_at))),node('td',M.kinds[r.kind]),node('td',prefix+r.number),node('td',r.actor_name),node('td',S.format(BigInt(r.delta))+' دینار'));$('#staff-cash-rows').append(row);}$('#staff-cash-paper').hidden=false;$('#staff-cash-empty').hidden=v.rows.length!==0;$('#staff-cash-print').disabled=$('#staff-cash-export').disabled=false;}
async function read(action){if(!active()){clear();location.replace('auth.html?next='+encodeURIComponent(destination));return;}const mine=++request,life=epoch,from=$('#staff-cash-from').value,to=$('#staff-cash-to').value,member=$('#staff-cash-member').value;clear();try{if(!members.has(member))throw Error('کارمەندێکی دوکانی خۆت هەڵبژێرە.');M.range(from,to);$('#staff-cash-status').textContent='پشکنینی مامەڵەکانی کارمەند…';const v=await KashierData.getOwnerCashierCashActivity(member,from,to);if(mine!==request||life!==epoch||!active())return;M.ownerReport(v,owner,member,from,to);render(v);$('#staff-cash-status').textContent=S.format(v.rows.length)+' مامەڵە · مامەڵەکانی کارمەندی هەڵبژێردراو';if(action==='print')window.print();if(action==='export'){const url=URL.createObjectURL(new Blob([M.csv(v)],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=url;a.download='cashier-cash-'+member+'-'+from+'-'+to+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(e){if(mine===request&&life===epoch){clear();$('#staff-cash-status').textContent=e.message;}}}
async function loadMembers(){const mine=++rosterRequest,life=epoch;invalidate();members.clear();$('#staff-cash-member').replaceChildren(node('option','کارمەند هەڵبژێرە'));$('#staff-cash-member').children[0].value='';if(!active()){location.replace('auth.html?next='+encodeURIComponent(destination));return;}try{const v=await KashierData.getStaffWorkspace();if(mine!==rosterRequest||life!==epoch||!active())return;S.workspace(v,owner);for(const c of v.cashiers){members.set(c.member_id,c);const option=node('option',c.member_name+' · '+(c.enabled?(c.accepted_at?'چالاک':'چاوەڕێی قبوڵکردن'):'ڕاگیراوە'));option.value=c.member_id;$('#staff-cash-member').append(option);}$('#staff-cash-status').textContent=v.cashiers.length?'کارمەند و ماوە هەڵبژێرە.':'هێشتا هیچ کارمەندێکت نییە.';if(initial){const selected=initial;initial=null;if(!members.has(selected.member)){$('#staff-cash-status').textContent='کارمەندی ئەم بەستەرە لە دوکانەکەت نییە.';return;}$('#staff-cash-member').value=selected.member;$('#staff-cash-from').value=selected.from;$('#staff-cash-to').value=selected.to;read();}else if(initialError){initialError=false;$('#staff-cash-status').textContent='بەستەری ڕاپۆرتەکە نادروستە؛ کارمەند و ماوە هەڵبژێرە.';}}catch(e){if(mine===rosterRequest&&life===epoch){members.clear();$('#staff-cash-member').replaceChildren();clear();$('#staff-cash-status').textContent=e.message;}}}
$('#owner-cash-refresh').addEventListener('click',loadMembers);
$('#staff-cash-form').addEventListener('submit',e=>{e.preventDefault();read();});for(const key of ['from','to','member'])$('#staff-cash-'+key).addEventListener('input',invalidate);$('#staff-cash-print').addEventListener('click',()=>{if(current)read('print');});$('#staff-cash-export').addEventListener('click',()=>{if(current)read('export');});window.addEventListener('pagehide',()=>{epoch++;rosterRequest++;members.clear();$('#staff-cash-member').replaceChildren();invalidate();});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});window.addEventListener('beforeprint',()=>{if(!active())clear();});const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),today=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');$('#staff-cash-from').value=$('#staff-cash-to').value=today;clear();if(!active())location.replace('auth.html?next='+encodeURIComponent(destination));else if(!S.uuid(owner))$('#staff-cash-status').textContent='ناسنامەی دوکان نادروستە.';else loadMembers();
})();
